import sys
from bisect import bisect_right

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(v) for v in data[1:1 + n]]
    divs = {}
    # pre[p][L] = number of divisors of p that are <= L (L clamped to p)
    pre = {}
    def count_upto(p, L):
        if L <= 0:
            return 0
        t = pre.get(p)
        if t is None:
            t = [0] * (p + 1)
            for d in range(1, p + 1):
                if p % d == 0:
                    t[d] = 1
            for d in range(1, p + 1):
                t[d] += t[d - 1]
            pre[p] = t
        return t[L if L < p else p]
    mxv, mxl = [], []
    mnv, mnl = [], []
    ans = 0
    for r in range(n):
        x = a[r]
        lo = r
        while mxv and mxv[-1] <= x:
            mxv.pop(); lo = mxl.pop()
        mxv.append(x); mxl.append(lo)
        lo = r
        while mnv and mnv[-1] >= x:
            mnv.pop(); lo = mnl.pop()
        mnv.append(x); mnl.append(lo)
        A = len(mxv); B = len(mnv)
        i = j = 0
        while i < A and j < B:
            l1 = mxl[i] if mxl[i] > mnl[j] else mnl[j]
            e1 = mxl[i + 1] - 1 if i + 1 < A else r
            e2 = mnl[j + 1] - 1 if j + 1 < B else r
            e = e1 if e1 < e2 else e2
            p = mxv[i] * mnv[j]
            if p == 0:
                ans += e - l1 + 1
            else:
                # lengths r - e + 1 .. r - l1 + 1
                ans += count_upto(p, r - l1 + 1) - count_upto(p, r - e)
            if e1 == e:
                i += 1
            if e2 == e:
                j += 1
    print(ans)

